CREATE TABLE IF NOT EXISTS erp_print_config(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO erp_print_config(id,enabled) VALUES(1,0);
CREATE TABLE IF NOT EXISTS erp_print_agents(id TEXT PRIMARY KEY,name TEXT NOT NULL,token_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,last_seen TEXT,version TEXT,inventory TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS erp_print_types(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS erp_print_formats(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,width_mm REAL NOT NULL CHECK(width_mm>0),height_mm REAL NOT NULL CHECK(height_mm>0),orientation TEXT NOT NULL CHECK(orientation IN ('portrait','landscape')));
CREATE TABLE IF NOT EXISTS erp_print_templates(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,type_id INTEGER NOT NULL REFERENCES erp_print_types(id),format_id INTEGER NOT NULL REFERENCES erp_print_formats(id),renderer TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS erp_work_center_printers(work_center_id INTEGER NOT NULL REFERENCES erp_work_centers(id),printer_id INTEGER NOT NULL REFERENCES erp_printers(id),type_id INTEGER NOT NULL REFERENCES erp_print_types(id),format_id INTEGER NOT NULL REFERENCES erp_print_formats(id),priority INTEGER NOT NULL DEFAULT 100,is_default INTEGER NOT NULL DEFAULT 0,manual_allowed INTEGER NOT NULL DEFAULT 1,is_alternative INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(work_center_id,printer_id,type_id,format_id));
CREATE UNIQUE INDEX IF NOT EXISTS erp_print_unique_default ON erp_work_center_printers(work_center_id,type_id,format_id) WHERE is_default=1 AND active=1;
CREATE TABLE IF NOT EXISTS erp_print_jobs(id TEXT PRIMARY KEY,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,user_id INTEGER NOT NULL,work_center_id INTEGER NOT NULL,template_id INTEGER NOT NULL,type_id INTEGER NOT NULL,format_id INTEGER NOT NULL,printer_id INTEGER NOT NULL,agent_id TEXT NOT NULL,queue_name TEXT NOT NULL,language TEXT NOT NULL,dpi INTEGER NOT NULL,copies INTEGER NOT NULL CHECK(copies BETWEEN 1 AND 100),mime TEXT NOT NULL,content BLOB,content_hash TEXT NOT NULL,request_key TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','reserved','processing','spooler_accepted','completed','error','cancelled','unknown')),attempts INTEGER NOT NULL DEFAULT 0,lease_token TEXT,lease_until TEXT,error TEXT,spool_id TEXT,started_at TEXT,finished_at TEXT,UNIQUE(user_id,request_key));
CREATE INDEX IF NOT EXISTS erp_print_pending ON erp_print_jobs(agent_id,state,created_at);
CREATE TABLE IF NOT EXISTS erp_print_audit(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,actor TEXT NOT NULL,event TEXT NOT NULL,job_id TEXT,detail TEXT);
